-- Isolated schema fixture captured from read-only live metadata; never applied to Cloud.
CREATE ROLE anon; CREATE ROLE authenticated;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
CREATE TYPE public.worker_role AS ENUM ('मिस्त्री','मजदूर','हेल्पर','ठेकेदार');
CREATE TYPE public.attendance_status AS ENUM ('Present','Absent','Half-Day');
CREATE TYPE public.brick_entry_type AS ENUM ('In','Out');
CREATE TYPE public.cashbook_type AS ENUM ('income','expense');
CREATE TYPE public.cashbook_category AS ENUM ('material','labor','transport','other');
CREATE TABLE public.attendance (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, worker_id uuid NOT NULL, date date NOT NULL DEFAULT CURRENT_DATE, status public.attendance_status NOT NULL DEFAULT 'Present'::attendance_status, advance integer NOT NULL DEFAULT 0, site_name text, notes text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), gps_status text, gps_lat numeric, gps_lng numeric, in_time time without time zone, out_time time without time zone, total_hours numeric DEFAULT 0, overtime_hours numeric DEFAULT 0);
CREATE TABLE public.attendance_logs (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), worker_id uuid NOT NULL, office_location_id uuid, attendance_type text NOT NULL DEFAULT 'in'::text, logged_at timestamp with time zone NOT NULL DEFAULT now(), log_date date NOT NULL DEFAULT CURRENT_DATE, latitude numeric, longitude numeric, distance_meters numeric, face_verified boolean NOT NULL DEFAULT false, site_name text, notes text, created_at timestamp with time zone NOT NULL DEFAULT now(), photo_url text, accuracy_meters numeric, is_suspicious boolean NOT NULL DEFAULT false, suspicious_reason text, review_status text NOT NULL DEFAULT 'approved'::text, reviewed_by uuid, reviewed_at timestamp with time zone);
CREATE TABLE public.brick_stock (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, date date NOT NULL DEFAULT CURRENT_DATE, site_name text, entry_type public.brick_entry_type NOT NULL DEFAULT 'In'::brick_entry_type, quantity integer NOT NULL DEFAULT 0, rate numeric NOT NULL DEFAULT 0, notes text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public.cashbook (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, date date NOT NULL DEFAULT CURRENT_DATE, type public.cashbook_type NOT NULL, category public.cashbook_category NOT NULL DEFAULT 'other'::cashbook_category, amount integer NOT NULL DEFAULT 0, site_name text, notes text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), payment_id uuid, worker_id uuid);
CREATE TABLE public.contractors (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, phone text, site_name text, contract_amount integer NOT NULL DEFAULT 0, advance_paid integer NOT NULL DEFAULT 0, notes text, is_active boolean NOT NULL DEFAULT true, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'चालू'::text, progress integer NOT NULL DEFAULT 0, upi_id text, address text, work_type text, start_date date, end_date date, payment_mode text DEFAULT 'नकद'::text, assigned_workers uuid[] DEFAULT '{}'::uuid[]);
CREATE TABLE public.material_entries (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, entry_date date NOT NULL DEFAULT CURRENT_DATE, site_name text NOT NULL, material_type text NOT NULL, quantity numeric NOT NULL, unit text NOT NULL, supplier_vehicle text, total_amount numeric NOT NULL DEFAULT 0, payment_status text NOT NULL DEFAULT 'unpaid'::text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public.office_locations (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL DEFAULT 'मुख्य ऑफिस'::text, latitude numeric NOT NULL, longitude numeric NOT NULL, radius_meters integer NOT NULL DEFAULT 50, face_scan_enabled boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public.payment_history (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid DEFAULT auth.uid(), worker_id uuid NOT NULL, amount numeric NOT NULL, payment_date date NOT NULL DEFAULT CURRENT_DATE, payment_mode text NOT NULL DEFAULT 'cash'::text, note text, site_name text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.sites (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, owner_name text NOT NULL DEFAULT ''::text, is_active boolean NOT NULL DEFAULT false, legacy_local_id text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public.worker_expenses (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), worker_id uuid NOT NULL, date date NOT NULL DEFAULT CURRENT_DATE, category text NOT NULL DEFAULT 'other'::text, amount numeric NOT NULL DEFAULT 0, site_name text, note text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), user_id uuid DEFAULT auth.uid());
CREATE TABLE public.workers (id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, role public.worker_role NOT NULL DEFAULT 'मजदूर'::worker_role, daily_rate integer NOT NULL DEFAULT 500, site_name text, phone text, is_active boolean NOT NULL DEFAULT true, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), upi_id text, worker_code text, linked_user_id uuid, photo_url text);
ALTER TABLE public.attendance ADD UNIQUE(worker_id,date);
ALTER TABLE public.attendance ADD FOREIGN KEY(worker_id) REFERENCES public.workers(id) ON DELETE CASCADE;
ALTER TABLE public.attendance_logs ADD FOREIGN KEY(worker_id) REFERENCES public.workers(id) ON DELETE CASCADE;
ALTER TABLE public.attendance_logs ADD FOREIGN KEY(office_location_id) REFERENCES public.office_locations(id) ON DELETE SET NULL;
ALTER TABLE public.worker_expenses ADD FOREIGN KEY(worker_id) REFERENCES public.workers(id) ON DELETE CASCADE;
ALTER TABLE public.payment_history ADD FOREIGN KEY(worker_id) REFERENCES public.workers(id) ON DELETE CASCADE;
ALTER TABLE public.cashbook ADD FOREIGN KEY(worker_id) REFERENCES public.workers(id) ON DELETE SET NULL;
ALTER TABLE public.cashbook ADD FOREIGN KEY(payment_id) REFERENCES public.payment_history(id) ON DELETE CASCADE;
CREATE UNIQUE INDEX sites_owner_name ON public.sites(user_id,lower(regexp_replace(btrim(name),'\s+',' ','g')));
GRANT USAGE ON SCHEMA public,auth TO authenticated;
GRANT EXECUTE ON FUNCTION auth.uid() TO authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.attendance TO authenticated; ALTER TABLE public.attendance ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.attendance TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.attendance_logs TO authenticated; ALTER TABLE public.attendance_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.attendance_logs TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.brick_stock TO authenticated; ALTER TABLE public.brick_stock ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.brick_stock TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cashbook TO authenticated; ALTER TABLE public.cashbook ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.cashbook TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contractors TO authenticated; ALTER TABLE public.contractors ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.contractors TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.material_entries TO authenticated; ALTER TABLE public.material_entries ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.material_entries TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.office_locations TO authenticated; ALTER TABLE public.office_locations ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.office_locations TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.payment_history TO authenticated; ALTER TABLE public.payment_history ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.payment_history TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sites TO authenticated; ALTER TABLE public.sites ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.sites TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.worker_expenses TO authenticated; ALTER TABLE public.worker_expenses ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.worker_expenses TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workers TO authenticated; ALTER TABLE public.workers ENABLE ROW LEVEL SECURITY; CREATE POLICY own ON public.workers TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
